return ['project-id-version'=>'Google Authenticator 0.59','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/google-authenticator/','po-revision-date'=>'2026-11-26 14:12+0000','last-translator'=>'','language-team'=>'Dutch','language'=>'nl_NL','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','plural-forms'=>'nplurals=2; plural=n != 1;','x-domain'=>'google-authenticator','messages'=>[' Description that you\'ll see in the Google Authenticator app on your phone.'=>' Omschrijving die je ziet in de Google Authenticator app op je mobiele apparaat.',' Enabling an App password will decrease your overall login security.'=>' Als je een app-wachtwoord inschakelt, wordt je inlogbeveiliging als geheel minder sterk.',' Password is not stored in cleartext, this is your only chance to see it.'=>' Wachtwoord wordt niet als platte tekst opgeslagen, dit is je enige kans om het te zien.',' Relaxed mode allows for more time drifting on your phone clock (&#177;4 min).'=>' Ontspannen modus geeft meer ruimte voor een afwijkende klok op je mobiele apparaat (&#177;4 min).','<strong>ERROR</strong>: Google Authenticator was not turned on. Add the site to your authenticator app by scanning the QR code, then enter the code the app shows.'=>'<strong>FOUT</strong>: Google Authenticator is niet ingeschakeld. Voeg de site toe aan je authenticator-app door de QR-code te scannen en typ daarna de code die de app toont.','<strong>ERROR</strong>: Please enter your Google Authenticator code.'=>'<strong>FOUT</strong>: Voer je Google Authenticator-code in.','<strong>ERROR</strong>: The Google Authenticator code is missing.'=>'<strong>FOUT</strong>: De Google Authenticator-code ontbreekt.','<strong>ERROR</strong>: The Google Authenticator password is incorrect.'=>'<strong>FOUT</strong>: Het Google Authenticator-wachtwoord is onjuist.','<strong>ERROR</strong>: The username, password or Google Authenticator code is incorrect, or the code has expired.'=>'<strong>FOUT</strong>: De gebruikersnaam, het wachtwoord of de Google Authenticator-code is onjuist, of de code is verlopen.','<strong>ERROR</strong>: Too many incorrect Google Authenticator codes. Please try again in %d minute.'=>'<strong>FOUT</strong>: Te veel onjuiste Google Authenticator-codes. Probeer het over %d minuut opnieuw.' . "\0" . '<strong>FOUT</strong>: Te veel onjuiste Google Authenticator-codes. Probeer het over %d minuten opnieuw.','<strong>ERROR</strong>: Your new Google Authenticator secret was not saved. Scan the new QR code with your authenticator app, then enter the code the app shows.'=>'<strong>FOUT</strong>: Je nieuwe geheime code voor Google Authenticator is niet opgeslagen. Scan de nieuwe QR-code met je authenticator-app en typ daarna de code die de app toont.','Active'=>'Actief','After adding the site to your authenticator app, type the code it shows here.'=>'Nadat je de site aan je authenticator-app hebt toegevoegd, typ je hier de code die de app toont.','An account can also be added by typing in the secret. After you\'ve added your account to the App, please type the code you see on the screen into the Authenticator Code field and press the Verify Authenticator Code button.'=>'Je kunt een account ook toevoegen door de geheime code in te typen. Nadat je je account in de app hebt toegevoegd, typ je de code die je op het scherm ziet in het veld Authenticatiecode en klik je op de knop Verifieer authenticatiecode.','Android: Authy'=>'Android: Authy','Android: Google Authenticator'=>'Android: Google Authenticator','Android: Microsoft Authenticator'=>'Android: Microsoft Authenticator','Ask for authenticator code on secondary login screen'=>'Vraag naar de authenticatiecode op een secundair inlogscherm','Authenticator Code'=>'Authenticatiecode','Change network wide Google Authenticator settings'=>'Netwerkbrede Google Authenticator-instellingen wijzigen','Congratulations, you have successfully enabled Google Authenticator for your account'=>'Gefeliciteerd, je hebt Google Authenticator met succes ingeschakeld voor je account','Create new password'=>'Nieuw wachtwoord maken','Create new secret'=>'Nieuwe geheime code maken','Description'=>'Omschrijving','Enable App password'=>'App-wachtwoord inschakelen','Google Authenticator'=>'Google Authenticator','Google Authenticator Settings'=>'Google Authenticator-instellingen','Google Authenticator code'=>'Google Authenticator-code','Hide settings from user'=>'Instellingen verbergen voor gebruiker','If the account setup was successful, you will be logged out, and will need to login again using your Username, Password and Authenticator code generated using the App on your mobile device.'=>'Als het instellen van het account is gelukt, word je uitgelogd en moet je opnieuw inloggen met je gebruikersnaam, wachtwoord en de authenticatiecode die de app op je mobiele apparaat genereert.','If you don\'t have Google Authenticator enabled for your WordPress account, leave this field empty.'=>'Als Google Authenticator niet is ingeschakeld voor je WordPress-account, laat dit veld dan leeg.','If you haven\'t already done so, please install an authenticator app on your mobile device, for example:'=>'Als je dat nog niet hebt gedaan, installeer dan een authenticator-app op je mobiele apparaat, bijvoorbeeld:','Log In'=>'Inloggen','Network Settings'=>'Netwerkinstellingen','Network-wide settings in effect, only a super admin can modify them.'=>'Netwerkbrede instellingen zijn van kracht, alleen een superbeheerder kan deze wijzigen.','OTP code doesn\'t match supplied secret, please check you\'ve configured Authenticator correctly.'=>'OTP-code komt niet overeen met de opgegeven geheime code, controleer of je de authenticator-app goed hebt ingesteld.','Only use network-wide settings, ignoring site settings.'=>'Gebruik alleen instellingen voor het hele netwerk en negeer de instellingen van de site.','Please enter the Google Authenticator code using the app on your device.'=>'Voer de Google Authenticator-code in met behulp van de app op je mobiele apparaat.','Relaxed mode'=>'Ontspannen modus','Roles requiring Google Authenticator Enabled'=>'Rollen waarvoor Google Authenticator vereist is','Scan this with the Google Authenticator app.'=>'Scan dit met de Google Authenticator-app.','Secondary Login Screen'=>'Secundair inlogscherm','Secret'=>'Geheime code','Show/Hide QR code'=>'Toon/verberg QR-code','Sorry, this role is enabled at the network level and can only be disabled via the <a href="%s">network settings</a>'=>'Sorry, deze rol is ingeschakeld op netwerkniveau en kan alleen worden uitgeschakeld via de <a href="%s">netwerkinstellingen</a>','Sorry, you can\'t disable checks for this role as it\'s enabled at the network level.'=>'Sorry, je kunt de controles voor deze rol niet uitschakelen omdat deze op netwerkniveau is ingeschakeld.','Successfully saved your settings for the network'=>'Instellingen succesvol opgeslagen voor het netwerk','Successfully saved your settings for the site'=>'Instellingen succesvol opgeslagen voor de site','Super Admins'=>'Superbeheerders','The easiest way to enable your account is to add an account by scanning the QR code using the app.'=>'De makkelijkste manier om je account in te schakelen is een account toe te voegen door het scannen van de QR-code met de app.','Two Screen Signin'=>'Aanmelden op twee schermen','Verify Authenticator Code'=>'Verifieer authenticatiecode','iOS: Authy'=>'iOS: Authy','iOS: Google Authenticator'=>'iOS: Google Authenticator','iOS: Microsoft Authenticator'=>'iOS: Microsoft Authenticator']];
